package com.tanidikvar.api.discussion.service;import com.tanidikvar.api.common.dto.*;import com.tanidikvar.api.common.error.DomainException;import com.tanidikvar.api.discussion.dto.*;import com.tanidikvar.api.discussion.repository.DiscussionRepository;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service public class DiscussionService{private final DiscussionRepository repository;public DiscussionService(DiscussionRepository repository){this.repository=repository;}@Transactional public AnswerCommentResponse add(UUID answer,UUID user,AnswerCommentRequest request){if(!repository.visibleAnswer(answer))throw new DomainException(404,"NOT_FOUND","Yanıt bulunamadı.");return repository.add(answer,user,request.body());}@Transactional(readOnly=true)public PageResponse<AnswerCommentResponse> list(UUID answer,int page,int size){SearchQuery.page(page,size);if(!repository.visibleAnswer(answer))throw new DomainException(404,"NOT_FOUND","Yanıt bulunamadı.");return new PageResponse<>(repository.list(answer,page,size),page,size,repository.count(answer));}@Transactional public AnswerCommentResponse update(UUID answer,UUID comment,UUID user,AnswerCommentUpdateRequest request){if(!repository.visibleAnswer(answer))throw new DomainException(404,"NOT_FOUND","Yanıt bulunamadı.");var current=repository.comment(answer,comment).orElseThrow(()->new DomainException(404,"NOT_FOUND","Alt yorum bulunamadı."));if(!current.authorId().equals(user))throw new DomainException(403,"ACCESS_DENIED","Yalnız kendi alt yorumunu düzenleyebilirsin.");if(current.version()!=request.version())throw new DomainException(409,"STALE_VERSION","Alt yorum değişmiş; sayfayı yenile.");repository.update(comment,request.body());return repository.comment(answer,comment).orElseThrow();}@Transactional public void best(UUID question,UUID user,BestAnswerRequest request){if(!repository.best(question,request.answerId(),user))throw new DomainException(403,"BEST_ANSWER_NOT_ALLOWED","Yalnız soru sahibi görünür bir yanıtı seçebilir.");}@Transactional(readOnly=true)public List<QuestionTemplateResponse> templates(String category){return repository.templates(category==null?"":category.trim().toUpperCase(Locale.forLanguageTag("tr")));}}
